    // Viewport-based visibility checks need at least one laid-out frame
    // (widget trees + GlobalKey contexts can be temporarily inactive during
    // initial builds). Until then, fall back to the old dirname-based
    // predicate so the UI never shows a permanently-wrong state.
    final viewportVisibilityReady = useState(false);
    useEffect(() {
      // Wait an extra frame so GlobalKey contexts are fully mounted and
      // measured before we trust their geometry for viewport visibility.
      WidgetsBinding.instance.addPostFrameCallback((_) {
        WidgetsBinding.instance.addPostFrameCallback((__) {
          if (context.mounted) viewportVisibilityReady.value = true;
        });
      });
      return null;
    }, const []);

    // Mounted check for async callbacks (replaces State.mounted).
    bool isMounted() => context.mounted;

    // Seed initial controller values once (initState parity).
    final didSeed = useRef<bool>(false);
    if (!didSeed.value) {
      didSeed.value = true;
      if (immersive.value) immersiveCtrl.value = 1.0;
      // swipeUp starts collapsed (t=0); fixed is always at rest (t=1).

